CREATE TABLE [dbo].[message](	  [messageId] INT NOT NULL IDENTITY(1,1)	, [conversationId] INT NOT NULL	, [messageStatusId] INT NOT NULL	, [userId] SMALLINT NOT NULL	, [date] DATETIME NOT NULL	, [tQueue] DATETIME NULL	, [tWait] INT NOT NULL DEFAULT((0))	, [tRetention] INT NOT NULL DEFAULT((0))	, [tResponse] INT NOT NULL DEFAULT((0))	, [tWrapUp] TINYINT NOT NULL DEFAULT((0))	, [tSend] DATETIME NULL	, [isSender] BIT NOT NULL DEFAULT((0)))